// Owner: C. Snapshot types = the frozen contract (src/contract.ts, generated by
// `pnpm gen:contract` from contract/schema.json) plus "console extras": optional keys the
// mock feed sends that the contract does not have yet (proposed additions, server/README.md).
// All times are sim seconds since t0_utc.
import type * as C from "./contract";

export type LonLat = [number, number]; // every point list in the feed is [lon, lat]
export type Mode =
  | "PATROL" | "ECO" | "SENTINEL" | "DORMANT" | "SHADOWING" | "RETURNING" | "UNAVAILABLE";

export interface Boat extends C.Boat {
  hdg?: number; // degrees true
  sog?: number; // mm/s (contract PR #10)
  sog_kn?: number;
  role_text?: string;
  via?: number | null; // next hop toward shore, 0 = shore
  heard?: boolean; // false = the shore never received anything from this boat
}

export interface Contact extends C.Contact {
  name?: string | null;
  source?: "ais" | "camera" | "fused";
  sog_kn?: number;
  trail?: LonLat[];
  name_status?: string;
  anchor_status?: string;
  detected?: boolean; // truth view only
}

export interface Decision extends C.Decision {
  tier?: "delegated" | "held";
  actions?: ("confirm" | "stop" | "approve" | "decline")[];
  status?: string;
  boat?: number;
  route?: LonLat[] | null;
  answered?: number | null;
}

export type Alert = C.Alert;
export interface LogEvent extends C.Event { exercise?: boolean }
export type Link = C.Link1 & { m?: number | null };
export type Task = C.TaskView;

export interface Snapshot extends Omit<C.Snapshot, "boats" | "contacts" | "decisions" | "events" | "links"> {
  boats: Boat[];
  contacts: Contact[];
  decisions: Decision[];
  events: LogEvent[];
  links: Link[];
  type?: "snapshot";
  source?: string;
  seed?: number;
  t_exact?: number;
  t0_utc?: string;
  warp_mode?: "auto" | "manual" | "paused"; // server/feed.py (feature 25)
  warp_set?: number | "auto"; // the chosen warp, also while paused (server/feed.py)
  near_event?: boolean; // auto-warp slowed around a scripted or injected event
  narration?: { t: number; text: string }[]; // server/narrator.py, /shore only
  // watch-officer escalations recorded by the server (server/bridge.py); the officer's call
  escalations?: { id: string; track: string; t: number; note: string }[];
  // shore launch and battery swaps at Korsør, done by the shore crew (server/bridge.py, #116)
  launch?: boolean; // boats started docked and launched from the shore
  swaps?: Record<string, number>; // boat id -> sim s when its battery swap should be done
  // exercise conditions still in effect (server/bridge.py), each with the injects that undo it
  exercises?: ExerciseItem[];
}

export interface ExerciseItem {
  t: number;
  kind: string;
  text: string;
  origin: string; // "operator injection" | "exercise script"
  undo: Command[] | null; // null = cannot be undone in this run (e.g. battery_low, #116)
}

export interface SceneMsg {
  type: "scene";
  schema_version: number;
  source: string;
  t0_utc: string;
  segments: Record<string, LonLat[]>;
  stations: Record<string, LonLat>;
  shore: LonLat;
  stale_after_s: number;
  horizon_s: number;
  revisit_target_s?: number; // config/run.toml (D), via the server
  home_m?: number; // agent's "at the shore station" radius (agent/core.py HOME_M)
  // boat model ranges from config/boat.toml via the server (#88 rings), until #87 puts them per boat
  ranges?: { detect_ship_day_m: number; keep_in_view_m: number; standoff_m: number };
  // boat model numbers from config/boat.toml via the server: model values, not measured
  boat_model?: { speed_mps: number; endurance_s: number; reserve_s: number };
}

export interface Ack {
  type: "ack"; cmd: string | null; id: string | null; ok: boolean; error?: string;
  placed?: string; on?: string; offset_m?: number; // contact_start (feature 13)
}

/** Contract commands, plus console extras the mock accepts (ack, speed, pause, reset). */
export type Command =
  | C.Command
  | { cmd: "ack"; id: string }
  | { cmd: "escalate"; id: string; text: string; note: string }
  | { cmd: "speed"; value: number | "auto" }
  | { cmd: "pause"; on?: boolean }
  | { cmd: "reset"; seed?: number }
  | { cmd: "inject"; kind: "contact_start"; lat: number; lon: number; ais?: boolean }
  | { cmd: "inject"; kind: "boat_restore"; a: number };

export const T0_FALLBACK = "2026-11-03T10:15:00Z"; // scenarios/fixed.toml ais_t0 (UTC, unverified)
export const t0Of = (s: { t0_utc?: string } | null) => s?.t0_utc ?? T0_FALLBACK;

/** Evaluator comparison, only on /truth frames (server/evaluator.py). Never on /shore. */
export interface EvalData {
  t: number;
  boats: {
    id: number; true: LonLat; shore: LonLat | null; offset_m: number | null; shore_age_s: number | null;
    true_link: string | null; shore_link: string | null; true_mode: string | null; shore_mode: string | null;
  }[];
  contacts: { id: string; track: string | null; pos: LonLat; ais: boolean | null; on_shore: boolean }[];
  links: { a: number; b: number; true: string; shore: string }[];
  seg_age: Record<string, { shore: number | null; true: number | null }>;
  /** True cable km past the revisit target (real sim only; null on the mock). */
  cable_overdue: { target_s: number; overdue_km: number; never_visited_km: number; total_km: number } | null;
}

/** Hook for D's three-mode scorecard (eval/), sent on /truth as "scorecard" when a source
 * offers it. Not built here: the console only shows what eval/ supplies. */
export interface Scorecard {
  source: string; // e.g. "eval/run_batch.py"
  seeds: number[];
  rows: { mode: string; metric: string; median: number; min: number; max: number; unit: string }[];
  preliminary?: boolean; // eval prints PRELIMINARY: show the word, never pass it off as final
}

/** #88 item 8: the watch officer's screen is the default (no truth view, no evaluator controls).
 * ?evaluator in the URL adds them and turns the evaluator comparison on. ?operator is still
 * accepted and means the default. */
export const EVALUATOR_MODE = new URLSearchParams(window.location.search).has("evaluator");
export const OPERATOR_MODE = !EVALUATOR_MODE;
